using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using IdleRestaurant;using RestaurantPreview;
public static class AllSeatedLooks053 {public static object Main(){var a=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();var root=new GameObject("Isolated seated shape review");root.transform.position=new Vector3(100,0,0);var rows=new List<object>();float minThigh=float.MaxValue,minCalf=float.MaxValue;foreach(var prefab in a.catalog.guestVariants)foreach(float yaw in new[]{-90f,90f}){var person=new Person(root.transform,new Vector3(0,.23f,0),prefab);person.root.localScale=Vector3.one*.85f;RestaurantAnimation.Pose(person,HumanMotion.Eating,0,new Vector3(0,.23f,0),yaw,0,.5f,true);float thigh=Mathf.Min(person.leftLeg.Find("Capsule").GetComponent<Renderer>().bounds.min.y,person.rightLeg.Find("Capsule").GetComponent<Renderer>().bounds.min.y)-.49f;Vector3 f=Quaternion.Euler(0,yaw,0)*Vector3.back;Vector3 chair=root.transform.position-f*.24f;float calf=float.MaxValue;foreach(var k in new[]{person.leftKnee,person.rightKnee})foreach(var r in k.GetComponentsInChildren<Renderer>()){var b=r.bounds;calf=Mathf.Min(calf,Vector3.Dot(b.center-chair,f)-Math.Abs(f.x)*b.extents.x-Math.Abs(f.z)*b.extents.z-.325f);}minThigh=Math.Min(minThigh,thigh);minCalf=Math.Min(minCalf,calf);rows.Add(new{prefab=prefab.name,yaw,thighClearance=thigh,calfAndShoeClearance=calf});person.root.gameObject.SetActive(false);UnityEngine.Object.Destroy(person.root.gameObject);}UnityEngine.Object.Destroy(root);var result=new{status=minThigh>=-.001&&minCalf>=-.001?"PASS":"FAIL",poses=rows.Count,minThigh,minCalf,rows,scope="All twelve authored prefabs at actual 0.85 guest scale, eating pose, both chair orientations; cushion-top and front-edge renderer-bound clearances"};File.WriteAllText("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/AllSeatedLooks.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{result.status,result.poses,minThigh,minCalf};}}
